// W2 step 2 – Lewis people. Mode: Run Once for All Items.
// Input: rows from lewis_people.csv (Extract from File → CSV).
const rows = $input.all().map(({ json: r }) => ({
  id: r.person_id,
  name: r.name,
  figureLabel: r.figure_label || null,
  inFigure: r.in_figure === 'true',
  show: r.show || null,
}));

const statement = `
UNWIND $rows AS r
MERGE (p:Person {id: r.id})
SET p.name = r.name, p.figureLabel = r.figureLabel, p.inFigure = r.inFigure,
    p.show = r.show, p.source = 'Lewis 2018, Appendix B'`;

return [{ json: { step: 'People', count: rows.length, body: { statement, parameters: { rows } } } }];

// W2 step 3 – Person -[:RUNS]-> Channel. Mode: Run Once for All Items.
// Input: rows from lewis_channels.csv (Extract from File → CSV).
// Channels Lewis lists but Recfluence doesn't have are stored on the Person as a list, so the agent can mention them.
const all = $input.all().map(i => i.json);

const runs = all.filter(r => r.recfluence_channel_id).map(r => ({
  personId: r.person_id,
  channelId: r.recfluence_channel_id,
  lewisName: r.lewis_channel_name,
  listedByLewis: r.listed_by_lewis === 'true',
  note: r.note || null,
}));

const unmatched = {};
for (const r of all.filter(r => !r.recfluence_channel_id && r.lewis_channel_name)) {
  (unmatched[r.person_id] ??= []).push(r.lewis_channel_name);
}
const missing = Object.entries(unmatched).map(([personId, names]) => ({ personId, names }));

// One request for both parts: two parallel requests touching the same Person nodes can deadlock.
const statement = `
UNWIND $runs AS r
MATCH (p:Person {id: r.personId})
MATCH (c:Channel {channelId: r.channelId})
MERGE (p)-[x:RUNS]->(c)
SET x.lewisChannelName = r.lewisName, x.listedByLewis = r.listedByLewis,
    x.note = r.note, x.source = 'Lewis 2018, Appendix B'
WITH count(x) AS runsWritten
CALL () {
  UNWIND $missing AS m
  MATCH (p:Person {id: m.personId})
  SET p.channelsNotInRecfluence = m.names
  RETURN count(p) AS peopleWithMissingChannels
}
RETURN runsWritten, peopleWithMissingChannels`;

return [{ json: { step: 'RUNS', count: runs.length, body: { statement, parameters: { runs, missing } } } }];

// W2 step 4 – Person -[:APPEARED_WITH]- Person. Mode: Run Once for All Items.
// Input: rows from lewis_edges.csv (Extract from File → CSV).
const BATCH_SIZE = 5000;   // one request: parallel batches deadlocked on shared nodes (see notes)
const num = v => (v === '' || v == null ? null : Number(v));

const rows = $input.all().map(({ json: r }) => ({
  a: r.a,
  b: r.b,
  confidence: r.confidence,            // high | medium | check
  fromFigure: r.from_figure === 'true',
  pixelCoverage: num(r.pixel_coverage),
  pixelRidge: num(r.pixel_ridge),
  note: r.note || null,
  evidence: r.evidence ? r.evidence.split(' | ') : [],
}));

const statement = `
UNWIND $rows AS r
MATCH (a:Person {id: r.a})
MATCH (b:Person {id: r.b})
MERGE (a)-[e:APPEARED_WITH]-(b)
SET e.confidence = r.confidence, e.fromFigure = r.fromFigure,
    e.pixelCoverage = r.pixelCoverage, e.pixelRidge = r.pixelRidge,
    e.note = r.note, e.evidence = r.evidence,
    e.source = 'Lewis 2018, Fig. 1', e.periodStart = date('2017-01-01'), e.periodEnd = date('2018-04-01')
RETURN count(e) AS written`;

const out = [];
for (let i = 0; i < rows.length; i += BATCH_SIZE) {
  const batch = rows.slice(i, i + BATCH_SIZE);
  out.push({ json: { step: 'APPEARED_WITH', batch: out.length + 1, count: batch.length, body: { statement, parameters: { rows: batch } } } });
}
return out;
